"""Auxiliary-IMU semantics and data-quality checks (HF-02).

The device IMU is a device-motion / static-gravity reference only; it is not a
human-impact sensor. Six-axis unit verification and orientation validity are
tracked separately. Magnitude clues (gravity-sized acceleration, near-zero
angular rate) are never accepted as scale or axis proof: units/alignment/bias
only become ``verified`` through a named evidence source (vendor protocol or a
controlled known motion/attitude).
"""

import math

from sensor_health import (finite_or_none, orientation_covariance_flags,
                           quaternion_report)

IMU_ROLE = "device_motion_gravity_reference_not_human_impact"
EVIDENCE_SOURCES = ("vendor_protocol", "controlled_motion", "controlled_attitude")
SEMANTIC_FIELDS = ("acceleration_units", "angular_velocity_units",
                   "axis_mapping", "bias")
DEFAULT_GRAVITY_M_S2 = 9.80665
ACCELERATION_UNITS_TO_SI = {"m_s2": 1.0, "g": DEFAULT_GRAVITY_M_S2}
ANGULAR_VELOCITY_UNITS_TO_SI = {"rad_s": 1.0, "deg_s": math.pi / 180.0}


def _validated_bias(value):
    try:
        values = [float(item) for item in value]
    except (TypeError, ValueError):
        raise ValueError("bias must be a sequence of six finite numbers") from None
    if len(values) != 6 or not all(math.isfinite(item) for item in values):
        raise ValueError("bias must be a sequence of six finite numbers")
    return values


# Reference-frame directions used by the supported axis_mapping triad, in a
# right-handed forward/left/up frame (ROS REP-103 style). Only the direction
# names are defined here; the device's actual mounting stays unknown.
REFERENCE_DIRECTIONS = {
    "forward": (1.0, 0.0, 0.0),
    "backward": (-1.0, 0.0, 0.0),
    "left": (0.0, 1.0, 0.0),
    "right": (0.0, -1.0, 0.0),
    "up": (0.0, 0.0, 1.0),
    "down": (0.0, 0.0, -1.0),
}


def _validated_axis_mapping(value):
    """Validate the supported three-axis mapping description.

    Accepted form: ``x_<direction>_y_<direction>_z_<direction>``. It is read
    ``from`` each IMU sensor axis ``x``/``y``/``z`` (listed once, in order)
    ``to`` the direction it points to in the reference frame. The directions
    must be known names, pairwise distinct and form a proper (right-handed)
    rotation, so text such as ``unknown``, missing/duplicate axes, duplicate
    directions and mirrored triads are rejected before any state change. This
    validates the description only; it never guesses the real device axes.
    """
    if not isinstance(value, str):
        raise ValueError("axis_mapping must be a supported triad string")
    tokens = value.split("_")
    if len(tokens) != 6 or tokens[0::2] != ["x", "y", "z"]:
        raise ValueError("axis_mapping must be "
                         "'x_<direction>_y_<direction>_z_<direction>' with each "
                         "sensor axis exactly once")
    directions = tokens[1::2]
    for name in directions:
        if name not in REFERENCE_DIRECTIONS:
            raise ValueError("unsupported axis direction: " + repr(name))
    if len(set(directions)) != 3:
        raise ValueError("axis direction conflict: two sensor axes point the same way")
    first, second, third = (REFERENCE_DIRECTIONS[name] for name in directions)
    cross = (first[1] * second[2] - first[2] * second[1],
             first[2] * second[0] - first[0] * second[2],
             first[0] * second[1] - first[1] * second[0])
    if cross != third:
        raise ValueError("axis_mapping is not a right-handed rotation of x/y/z")
    return value


class ImuSemantics:
    """Per-field verification state for the auxiliary device IMU."""

    def __init__(self):
        self.status = {field: "unknown" for field in SEMANTIC_FIELDS}
        self.values = {}
        self.evidence = []

    def verify(self, field, value, evidence, note=None):
        """Mark one semantic field verified by named evidence.

        The value itself is validated: empty values, unsupported unit names,
        invalid axis-mapping descriptions and wrong-sized/non-finite bias
        vectors are rejected before any state mutation, so neither an empty nor
        an arbitrary ``verify`` call can enable motion classification.
        """
        if field not in SEMANTIC_FIELDS:
            raise ValueError("unknown IMU semantic field: " + str(field))
        if evidence not in EVIDENCE_SOURCES:
            raise ValueError(
                "unsupported evidence {!r}: magnitude hints (gravity-sized "
                "acceleration, near-zero rate) are not scale proof".format(evidence))
        if field == "acceleration_units":
            if not isinstance(value, str) or value not in ACCELERATION_UNITS_TO_SI:
                raise ValueError("unsupported acceleration units: " + repr(value))
        elif field == "angular_velocity_units":
            if not isinstance(value, str) or value not in ANGULAR_VELOCITY_UNITS_TO_SI:
                raise ValueError("unsupported angular velocity units: " + repr(value))
        elif field == "axis_mapping":
            value = _validated_axis_mapping(value)
        elif field == "bias":
            value = _validated_bias(value)
        self.status[field] = "verified"
        self.values[field] = value
        self.evidence.append({"field": field, "value": value, "evidence": evidence,
                              "note": note})
        return dict(self.report())

    @property
    def units_verified(self):
        return (self.status["acceleration_units"] == "verified"
                and self.status["angular_velocity_units"] == "verified")

    @property
    def alignment_verified(self):
        return self.status["axis_mapping"] == "verified"

    def report(self):
        return {"role": IMU_ROLE,
                "acceleration_units": self.status["acceleration_units"],
                "angular_velocity_units": self.status["angular_velocity_units"],
                "axis_mapping": self.status["axis_mapping"],
                "bias": self.status["bias"],
                "values": dict(self.values),
                "units_verified": self.units_verified,
                "alignment_verified": self.alignment_verified,
                "evidence": [dict(item) for item in self.evidence]}


def six_axis_report(acceleration, angular_velocity):
    """Finiteness of the six-axis measurement, kept separate from orientation.

    A usable six-axis sample is exactly three finite acceleration values and
    exactly three finite angular-velocity values; missing/extra axes or
    unreadable values are reported invalid instead of being treated as finite.
    """
    if acceleration is None or angular_velocity is None:
        return {"finite": None, "reason": None}
    try:
        accel = [float(value) for value in acceleration]
        rate = [float(value) for value in angular_velocity]
    except (TypeError, ValueError):
        return {"finite": False, "reason": "imu_measurement_malformed"}
    if len(accel) != 3 or len(rate) != 3:
        return {"finite": False, "reason": "imu_axis_count_invalid"}
    finite = all(math.isfinite(value) for value in accel + rate)
    return {"finite": finite,
            "reason": None if finite else "imu_measurement_nonfinite"}


def orientation_report(quaternion, covariance):
    """Orientation usability, reusing the frozen HF-01 rules.

    ``covariance[0] == -1`` (not provided) and all-zero/non-unit/non-finite
    quaternions are unusable; no valid quaternion is ever fabricated.
    """
    covariance_zero, not_provided = orientation_covariance_flags(covariance)
    if not_provided:
        usable, reason = False, "orientation_not_provided"
    elif quaternion is None:
        usable, reason = None, None
    else:
        usable, reason = quaternion_report(quaternion)
    return {"usable": usable, "reason": reason,
            "not_provided": bool(not_provided),
            "covariance_zero": bool(covariance_zero)}


def device_motion_status(acceleration, angular_velocity, semantics,
                         gravity_m_s2=DEFAULT_GRAVITY_M_S2,
                         accel_tolerance_m_s2=0.25,
                         rate_tolerance_rad_s=0.03):
    """Static/moving status of the device, only once units+axes are verified.

    Raw values are converted from the verified units (``m_s2``/``g`` and
    ``rad_s``/``deg_s``) to SI before the SI thresholds are compared; unknown
    or unsupported units keep the verdict ``unknown`` instead of silently
    assuming SI. Thresholds are the physical tuning knobs for the board
    installation. This is a device-motion hint only: bias/alignment and the
    static-background ground/background conditions stay separate, and this
    verdict alone never enables fusion.
    """
    if not semantics.units_verified:
        return {"status": "unknown", "reason": "imu_units_unverified",
                "scope": IMU_ROLE}
    if not semantics.alignment_verified:
        return {"status": "unknown", "reason": "imu_alignment_unverified",
                "scope": IMU_ROLE}
    accel_scale = ACCELERATION_UNITS_TO_SI.get(semantics.values.get("acceleration_units"))
    rate_scale = ANGULAR_VELOCITY_UNITS_TO_SI.get(
        semantics.values.get("angular_velocity_units"))
    if accel_scale is None or rate_scale is None:
        return {"status": "unknown", "reason": "imu_units_unverified",
                "scope": IMU_ROLE}
    report = six_axis_report(acceleration, angular_velocity)
    if report["finite"] is not True:
        return {"status": "unknown", "reason": report["reason"] or "imu_measurement_missing",
                "scope": IMU_ROLE}
    magnitude = math.sqrt(sum((float(value) * accel_scale) ** 2
                              for value in acceleration))
    max_rate = max(abs(float(value)) * rate_scale for value in angular_velocity)
    gravity_residual = abs(magnitude - float(gravity_m_s2))
    if gravity_residual <= float(accel_tolerance_m_s2) and max_rate <= float(rate_tolerance_rad_s):
        status = "static"
    else:
        status = "moving"
    return {"status": status, "reason": None, "scope": IMU_ROLE,
            "gravity_residual_m_s2": gravity_residual,
            "max_angular_rate": finite_or_none(max_rate),
            "comparison_units": "m_s2/rad_s"}


def static_background_usable(ground_valid, background_residual_ok, device_motion):
    """Gate the static-background scheme on ground, residual and device motion.

    A missing IMU motion verdict is not a pass: the IMU alone cannot prove the
    device did not translate, so unknown motion keeps the scheme unusable and
    asks for a fresh on-site initialisation along with the other failures.
    """
    reasons = []
    if ground_valid is not True:
        reasons.append("ground_invalid")
    if background_residual_ok is not True:
        reasons.append("background_residual_invalid")
    if device_motion != "static":
        reasons.append("device_motion_" + str(device_motion))
    usable = not reasons
    return {"usable": usable, "reinit_required": not usable, "reasons": reasons}

#!/usr/bin/env python3
"""Publish strict-JSON health for the point cloud, auxiliary IMU and device status. Read-only."""

import argparse
import json
import math
import os
import sys
import tempfile
import threading
import time

import numpy as np

SCHEMA_VERSION = 1
HEALTH_KIND = "health"
SOURCE_TIME_DOMAIN = "device_stamp_s_unanchored"
QUATERNION_UNIT_TOLERANCE = 1e-3
FLOAT32_DATATYPE = 7
FLOAT64_DATATYPE = 8
STAMP_STATUSES = ("none", "first", "ok", "repeated", "regressed", "forward_jump", "invalid")


def finite_or_none(value):
    if value is None:
        return None
    number = float(value)
    return number if math.isfinite(number) else None


def dumps_strict(payload):
    return json.dumps(payload, allow_nan=False)


def save_json(path, data):
    directory = os.path.abspath(os.path.dirname(path) or ".")
    os.makedirs(directory, exist_ok=True)
    temporary = None
    try:
        with tempfile.NamedTemporaryFile("w", encoding="utf-8", dir=directory,
                                         prefix=".human-fall-", suffix=".json",
                                         delete=False) as output:
            temporary = output.name
            json.dump(data, output, indent=2, ensure_ascii=False, allow_nan=False)
            output.write("\n")
        os.replace(temporary, path)
    finally:
        if temporary and os.path.exists(temporary):
            os.unlink(temporary)


def stamp_pair(header):
    return (int(header.secs), int(header.nsecs))


def valid_stamp(stamp):
    if stamp is None or len(stamp) != 2:
        return False
    secs, nsecs = int(stamp[0]), int(stamp[1])
    if secs < 0 or nsecs < 0 or nsecs >= 1000000000:
        return False
    return (secs, nsecs) != (0, 0)


def stamp_seconds(stamp):
    if not valid_stamp(stamp):
        return None
    return int(stamp[0]) + int(stamp[1]) / 1e9


def raw_stamp(stamp):
    """Raw integer sec/nsec of the current frame, kept even when the stamp is invalid."""
    if stamp is None or len(stamp) != 2:
        return None, None
    try:
        return int(stamp[0]), int(stamp[1])
    except (TypeError, ValueError):
        return None, None


def check_stamp(prefix, previous, current, max_forward_jump_s):
    """Classify a new source stamp. Returns (status, reason, discontinuity)."""
    if not valid_stamp(current):
        return "invalid", prefix + "_stamp_invalid", False
    if previous is None:
        return "first", None, False
    current_s = stamp_seconds(current)
    previous_s = stamp_seconds(previous)
    if current_s < previous_s:
        return "regressed", prefix + "_stamp_regressed", True
    if current_s == previous_s:
        return "repeated", prefix + "_stamp_repeated", True
    if current_s - previous_s > float(max_forward_jump_s):
        return "forward_jump", prefix + "_stamp_forward_jump", True
    return "ok", None, False


def orientation_covariance_flags(covariance):
    """Return (all_zero, not_provided) for the ROS Imu 9-element covariance array.

    All nine entries zero only mark the covariance as unknown; a first entry of -1
    means the orientation estimate is not provided and must be ignored.
    """
    values = [float(value) for value in covariance] if covariance is not None else []
    all_zero = len(values) == 9 and all(value == 0.0 for value in values)
    not_provided = bool(values) and values[0] == -1.0
    return all_zero, not_provided


def quaternion_report(quaternion):
    """Return (usable, reason). All-zero, non-finite and non-unit quaternions are unusable."""
    values = [float(value) for value in quaternion]
    if len(values) != 4 or not all(math.isfinite(value) for value in values):
        return False, "orientation_nonfinite"
    norm = math.sqrt(sum(value * value for value in values))
    if norm == 0.0:
        return False, "orientation_all_zero"
    if abs(norm - 1.0) > QUATERNION_UNIT_TOLERANCE:
        return False, "orientation_non_unit"
    return True, None


def pointcloud_layout(msg):
    """Validate PointCloud2 fields/offsets/datatypes/strides/endianness/data length."""
    errors = []
    try:
        width, height = int(msg.width), int(msg.height)
        point_step, row_step = int(msg.point_step), int(msg.row_step)
        bigendian = bool(msg.is_bigendian)
        raw_fields = list(msg.fields)
    except (AttributeError, TypeError, ValueError) as exc:
        return {"valid": False, "errors": ["unreadable_message:" + str(exc)],
                "width": None, "height": None, "point_step": None, "row_step": None,
                "data_bytes": 0, "required_bytes": None, "is_bigendian": None,
                "field_names": []}
    if width <= 0 or height <= 0:
        errors.append("invalid_dimensions")
    if point_step <= 0:
        errors.append("invalid_point_step")
    if row_step < width * point_step:
        errors.append("row_step_smaller_than_points")
    try:
        data = memoryview(msg.data)
        data_bytes = data.nbytes
    except (TypeError, ValueError):
        data = None
        data_bytes = 0
        errors.append("data_not_a_byte_buffer")
    required_bytes = max(0, row_step) * max(0, height)
    if data is not None and data_bytes < required_bytes:
        errors.append("truncated_data")
    fields = {}
    for field in raw_fields:
        name = str(field.name)
        if name in fields:
            errors.append("duplicate_field_" + name)
            continue
        fields[name] = field
    for name in ("x", "y", "z"):
        field = fields.get(name)
        if field is None:
            errors.append("missing_field_" + name)
            continue
        size = 4 if int(field.datatype) == FLOAT32_DATATYPE else 8
        if int(field.datatype) not in (FLOAT32_DATATYPE, FLOAT64_DATATYPE) or int(field.count) != 1:
            errors.append("bad_field_" + name)
        elif int(field.offset) < 0 or int(field.offset) + size > point_step:
            errors.append("field_outside_point_step_" + name)
    timestamp_field = fields.get("timestamp")
    if timestamp_field is None:
        errors.append("missing_field_timestamp")
    elif int(timestamp_field.datatype) != FLOAT64_DATATYPE or int(timestamp_field.count) != 1:
        errors.append("bad_field_timestamp")
    elif int(timestamp_field.offset) < 0 or int(timestamp_field.offset) + 8 > point_step:
        errors.append("field_outside_point_step_timestamp")
    return {"valid": not errors, "errors": errors,
            "width": width, "height": height,
            "point_step": point_step, "row_step": row_step,
            "data_bytes": data_bytes, "required_bytes": required_bytes,
            "is_bigendian": bigendian, "field_names": list(fields)}


def read_point_timestamps(msg):
    """Read the per-point float64 timestamp field at its declared (possibly unaligned) offset."""
    layout = pointcloud_layout(msg)
    if not layout["valid"]:
        raise ValueError("invalid PointCloud2 layout: " + ",".join(layout["errors"]))
    field = next(field for field in msg.fields if str(field.name) == "timestamp")
    try:
        data = memoryview(msg.data)
        dtype = np.dtype(">f8" if layout["is_bigendian"] else "<f8")
        array = np.ndarray((layout["height"], layout["width"]), dtype=dtype, buffer=data,
                           strides=(layout["row_step"], layout["point_step"]),
                           offset=int(field.offset))
        return np.asarray(array, dtype=np.float64).ravel()
    except (TypeError, ValueError) as exc:
        raise ValueError("cannot decode PointCloud2 timestamps: " + str(exc)) from exc


def point_value_summary(total_points, xyz):
    """Summarise decoded xyz points: finite/non-finite and all-zero (invalid-return) counts."""
    total = int(total_points)
    finite = int(len(xyz))
    zero = int(np.count_nonzero(np.all(np.asarray(xyz) == 0.0, axis=1))) if xyz.size else 0
    return {"total_points": total, "nonfinite_points": total - finite,
            "zero_points": zero, "finite_nonzero_points": finite - zero}


def _load_xyz_from_cloud():
    """Reuse human_follow_calibration.xyz_from_cloud instead of copying the decoder."""
    try:
        from calibrate_human_follow import CalibrationError, xyz_from_cloud
        return xyz_from_cloud, CalibrationError
    except ImportError:
        pass
    here = os.path.dirname(os.path.abspath(__file__))
    candidates = (os.path.join(here, "..", "human_follow_calibration"),
                  os.path.join(here, "..", "..", "human_follow_calibration", "scripts"))
    for candidate in candidates:
        candidate = os.path.abspath(candidate)
        if os.path.isfile(os.path.join(candidate, "calibrate_human_follow.py")):
            if candidate not in sys.path:
                sys.path.append(candidate)
    try:
        from calibrate_human_follow import CalibrationError, xyz_from_cloud
        return xyz_from_cloud, CalibrationError
    except ImportError:
        return None, None

#!/usr/bin/env python3
"""Calibrate one stationary LiDAR target. This program never commands a robot."""

import argparse
import json
import math
import os
import tempfile
import time
from datetime import datetime, timezone

import numpy as np


class CalibrationError(ValueError):
    pass


def positive_float(value):
    number = float(value)
    if not math.isfinite(number) or number <= 0:
        raise argparse.ArgumentTypeError("must be a positive finite number")
    return number


def xyz_from_cloud(msg, min_range_m):
    """Read x/y/z from organized or flat PointCloud2, including padded rows."""
    width, height = int(msg.width), int(msg.height)
    point_step, row_step = int(msg.point_step), int(msg.row_step)
    if width <= 0 or height <= 0 or point_step <= 0 or row_step < width * point_step:
        raise CalibrationError("invalid PointCloud2 dimensions or strides")
    try:
        data = memoryview(msg.data)
    except TypeError as exc:
        raise CalibrationError("PointCloud2 data is not a byte buffer") from exc
    if data.nbytes < row_step * height:
        raise CalibrationError("truncated PointCloud2 data")

    fields = {}
    for field in msg.fields:
        if field.name in ("x", "y", "z"):
            if field.name in fields:
                raise CalibrationError("duplicate PointCloud2 coordinate field: " + field.name)
            fields[field.name] = field
    if set(fields) != {"x", "y", "z"}:
        raise CalibrationError("PointCloud2 needs x, y and z fields")

    formats, offsets = [], []
    for name in ("x", "y", "z"):
        field = fields[name]
        if field.count != 1 or field.datatype not in (7, 8):  # PointField FLOAT32/FLOAT64
            raise CalibrationError("unsupported PointCloud2 field: " + name)
        size = 4 if field.datatype == 7 else 8
        if field.offset < 0 or field.offset + size > point_step:
            raise CalibrationError("PointCloud2 field exceeds point_step: " + name)
        formats.append(np.dtype((">" if msg.is_bigendian else "<") + ("f4" if size == 4 else "f8")))
        offsets.append(field.offset)
    try:
        dtype = np.dtype({"names": ["x", "y", "z"], "formats": formats,
                          "offsets": offsets, "itemsize": point_step})
        cloud = np.ndarray((height, width), dtype=dtype, buffer=data,
                           strides=(row_step, point_step))
        xyz = np.column_stack((cloud["x"].ravel(), cloud["y"].ravel(),
                               cloud["z"].ravel())).astype(np.float64, copy=False)
    except (ValueError, TypeError) as exc:
        raise CalibrationError("cannot decode PointCloud2 xyz: " + str(exc)) from exc
    xyz = xyz[np.isfinite(xyz).all(axis=1)]
    distance = np.hypot(np.hypot(xyz[:, 0], xyz[:, 1]), xyz[:, 2])
    return xyz[distance >= min_range_m]


def crop_roi(points, roi):
    return points[(points[:, 0] >= roi["x_min_m"]) & (points[:, 0] <= roi["x_max_m"])
                  & (points[:, 1] >= roi["y_min_m"]) & (points[:, 1] <= roi["y_max_m"])
                  & (points[:, 2] >= roi["z_min_m"]) & (points[:, 2] <= roi["z_max_m"])]


def voxel_keys(points, cell_xy_m, cell_z_m):
    grid = np.floor(points / (cell_xy_m, cell_xy_m, cell_z_m)).astype(np.int32)
    return np.ascontiguousarray(grid).view(np.dtype((np.void, 12))).ravel()

